head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst00406";
scwin.selCndt = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        $("#ipt_etnIsuSrtNm").bind("change", function() {
                $c.util.getComponent('ipt_etnIsuSrtCd').setValue("");
        });
        $("#ipt_reportNm").bind("change", function() {
                $c.util.getComponent('ipt_reportCd').setValue("");
        });
        $("#ipt_etnIsuSrtNm").bind("keypress", async function(e) {
                if (e.keyCode === 13) {
                    if ($c.util.getComponent('ipt_etnIsuSrtNm').getValue() !== $c.util.getComponent('ipt_etnIsuSrtCd').getValue()) {
                        $c.util.getComponent('ipt_etnIsuSrtCd').setValue("");
                    }
                    await scwin.fnSearchInit();
                }
        });
        $("#ipt_reportNm").bind("keypress", async function(e) {
                if (e.keyCode === 13) {
                    if ($c.util.getComponent('ipt_reportNm').getValue() !== $c.util.getComponent('ipt_reportTmp').getValue()) {
                        $c.util.getComponent('ipt_reportCd').setValue("");
                    }
                    await scwin.fnSearchInit();
                }
        });
        /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnDisplaySearchBtnDatesOnlyPeriod( "1 ') */
        await scwin.fnSearchInit();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst00406.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fnDownload();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.selCndt = selCndt;
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst00406.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
// [저작] 기간 프리셋 버튼 — fnDisplaySearchBtnDates 재설계 (btn_cm 텍스트·gcc date 조합)

