 */
scwin.slc_etpProdTpCd_onchange = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.selChange(selfVar.value)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst00406.slc_etpProdTpCd_onchange' }); }
};

