        await scwin.fnDownload();return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst00406.btn_fnDownload_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnDownload
 * @description fn Download 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnDownload = async function () {
    const sbmOptions = {
        id: "tx_fnDownload",
        method: "post",
        action: "/disclosure/disclosurebyetn.do",
        ref: "dma_fnDownloadReq",
        target: "dlt_disclosureByStockType=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnSearch_ajaxsubmit
 * @description fn Search ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/disclosure/disclosurebyetn.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name fnSearchInit
 * @description fn Search Init 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchInit = async function () {
    await scwin.fnOrder("1", "D");
};

/**
 * @method
 * @name fnOrder
 * @description fn Order 처리
 * @param {*} mode mode
 * @param {*} stat stat
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnOrder = async function (mode, stat) {
    $c.util.getComponent("dma_fnDownloadReq").set("orderMode", mode);
    $c.util.getComponent("dma_fnDownloadReq").set("orderStat", stat);
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    await scwin.fnSearch();
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    if (!$c.date.isDate($c.util.getComponent('cal_fromDate').getValue())) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return;
    }
    if (!$c.date.isDate($c.util.getComponent('cal_toDate').getValue())) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        return;
    }
    if (($c.util.getComponent('cal_fromDate').getValue() == null ? '' : String($c.util.getComponent('cal_fromDate').getValue())) !== '' && ($c.util.getComponent('cal_toDate').getValue() == null ? '' : String($c.util.getComponent('cal_toDate').getValue())) !== '') {
        if (!($c.date.diffDate($c.util.getComponent('cal_fromDate').getValue(), $c.util.getComponent('cal_toDate').getValue()) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
            return;
        }
    }
    if ($c.date.addYear($c.util.getComponent('cal_fromDate').getValue(), 3) < $c.date.addYear($c.util.getComponent('cal_toDate').getValue(), 0)) {
        await $c.win.alert("조회기간은  3년 이내만 가능합니다.");
        return;
    }
    if ($(document).find("select[id=ipt_currentPageSize]").val() != null) {
        $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    }
    $c.util.getComponent("dma_fnDownloadReq").set("method", "searchDisclosureByStockTypeEtnSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "disclosurebystocktype_etn_sub");
    await scwin.tx_fnSearch_ajaxsubmit();
};

/**
 * @method
 * @name fnSearchCallBack
 * @description fn Search Call Back 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCallBack = function (data) {
    $("#mainContents").empty().append(data);
    $("tr:even").addClass("active");
    /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnLegendTooltip( " ') */
};

/**
 * @method
 * @name fnDownload
 * @description fn Download 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnDownload = async function () {
    if (!$c.date.isDate($c.util.getComponent('cal_fromDate').getValue())) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return;
    }
    if (!$c.date.isDate($c.util.getComponent('cal_toDate').getValue())) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        return;
    }
    if (($c.util.getComponent('cal_fromDate').getValue() == null ? '' : String($c.util.getComponent('cal_fromDate').getValue())) !== '' && ($c.util.getComponent('cal_toDate').getValue() == null ? '' : String($c.util.getComponent('cal_toDate').getValue())) !== '') {
        if (!($c.date.diffDate($c.util.getComponent('cal_fromDate').getValue(), $c.util.getComponent('cal_toDate').getValue()) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
            return;
        }
    }
    if ($c.date.addYear($c.util.getComponent('cal_fromDate').getValue(), 3) < $c.date.addYear($c.util.getComponent('cal_toDate').getValue(), 0)) {
        await $c.win.alert("조회기간은  3년 이내만 가능합니다.");
        return;
    }
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", "3000");
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("method", "searchDisclosureByStockTypeEtnSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "disclosurebystocktype_etn_down");
    await scwin.tx_fnDownload();
};

/**
 * @method
 * @name listIdxSecuFind
 * @description list Idx Secu Find 처리
 * @param {String} isurCd isurCd
 * @returns {void}
 * @hidden N
 */
scwin.listIdxSecuFind = function (isurCd) {
    const url = "/disclosure/listidxsecudetailed.do?method=readListIdxSecuDetailedMain";
    const wTitle = "";
    const wWidth = 870;
    const wHeight = 920;
    const wSco = "yes";
    const wUrl = url + "&isurCd=" + isurCd;
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.win.openPopup((function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(wUrl), String('' || '').split(',').reduce(function (o, kv) { const p = kv.split('='); const k = (p[0] || '').replace(/\s/g, ''); const v = (p[1] || '').replace(/\s/g, ''); if (k === 'width' || k === 'height') { o[k] = v; } else if (k === 'scrollbars' || k === 'resizable' || k === 'modal') { o[k] = (v === 'yes' || v === '1'); } return o; }, (typeof wTitle !== 'undefined' ? wTitle : '') ? Object.assign({ width: "", height: "", scrollbars: false, resizable: false, type: "pageFramePopup" }, { id: (typeof wTitle !== 'undefined' ? wTitle : '') }) : { width: "", height: "", scrollbars: false, resizable: false, type: "pageFramePopup" }), {});
};

/**
 * @method
 * @name fnSearch1
 * @description fn Search1 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch1 = async function () {
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    await scwin.fnSearch();
};

/**
 * @method
 * @name setReportNameInfo
 * @description set Report Name Info 처리
 * @param {String} formCd formCd
 * @param {String} formNm formNm
 * @returns {void}
 * @hidden N
 */
scwin.setReportNameInfo = function (formCd, formNm) {
    $c.util.getComponent('ipt_reportNm').setValue(formNm);
    $c.util.getComponent('ipt_reportTmp').setValue(formNm);
    $c.util.getComponent('ipt_reportCd').setValue(formCd);
};

/**
 * @method
 * @name setEtnInfo
 * @description set Etn Info 처리
 * @param {String} isuSrtCd isuSrtCd
 * @param {*} isuKorAbbrv isuKorAbbrv
 * @param {String} isuCd isuCd
 * @returns {void}
 * @hidden N
 */
scwin.setEtnInfo = function (isuSrtCd, isuKorAbbrv, isuCd) {
    $c.util.getComponent('ipt_etnIsuSrtNm').setValue(isuSrtCd);
    $c.util.getComponent('ipt_etnIsuSrtCd').setValue(isuSrtCd);
};

function selCndt(val) {
    if (val === 'N') {
        $("select[name=earyRedmptCycleCd]").attr("disabled", true);
    } else {
        $("select[name=earyRedmptCycleCd]").attr("disabled", false);
    }
}

/**
 * @method
 * @name selChange
 * @description sel Change 처리
 * @param {*} val val
 * @returns {void}
 * @hidden N
 */
scwin.selChange = function (val) {
    let sel = "";
    for (let i = 0; i < (function(){ throw 'unresolved:list:typeList'; })(); i++) {
        sel += "<option value='${typeList[__i].cdVal}'>${typeList[__i].cdValNm}</option>";
    }
    if (val === '4') {
        let str = "<font color='#295890'><b>조기상환조건 여부</b></font> &nbsp;<select id='earyRedmptCondYn' name='earyRedmptCondYn' onChange='selCndt(this.value)'><option value='Y'>예</option><option value='N'>아니오</option></select>&nbsp;&nbsp;";
        str += "<font color='#295890'><b>조기상환조건 주기</b></font> <select name='earyRedmptCycleCd' id='earyRedmptCycleCd'><option value=''>전체</option>" + sel + "</select>";
        (($c.util.getComponent('txt_viewCondition')) && ($c.util.getComponent('txt_viewCondition')).setValue ? ($c.util.getComponent('txt_viewCondition')).setValue(str) : (($c.util.getComponent('txt_viewCondition')) && ($c.util.getComponent('txt_viewCondition')).setText ? ($c.util.getComponent('txt_viewCondition')).setText(str) : void (str)));
    } else {
        $("#txt_viewCondition").children().remove();
        $c.util.getComponent('txt_viewCondition').setLabel("");
    }
};
